        };
    
        function DrillDown_Callback(result) {
            if ( !result.Error ) {
                datalistInstance.reload();
            } else {
                alert(result.Error);
            }
        }

        document.addEventListener("DOMContentLoaded", function() {
            var isChildDataList = !!datalistInstance.prefix;
            if (isChildDataList) {
                return;
