            datalistInstance.toggleHeaderButtons(datalistInstance.data ? datalistInstance.data.ViewType : -1);

            window.newUI.contextMenuActions.registerButton("CopySmartlistAction", function(data) { return datalistInstance.copySmartList(data); });
